using System.Globalization;
using System.Text.Json;
using MySqlConnector;
namespace WoWItemEditor;
internal static class QuestEditing
{
    internal static string Events=>AppSettings.Current.BackupDatabase+".quest_editor_events";
    internal static async Task Initialize(MySqlConnection db){await CreatedQuests.Initialize(db);using var cmd=new MySqlCommand($"CREATE TABLE IF NOT EXISTS {Events}(EventId CHAR(36) PRIMARY KEY,OperationId CHAR(36) NOT NULL,Action VARCHAR(20) NOT NULL,BeforeJson LONGTEXT NOT NULL,AfterJson LONGTEXT NOT NULL,CreatedUtc DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",db);await cmd.ExecuteNonQueryAsync();}
    private static int N(IReadOnlyDictionary<string,string?> row,string key)=>int.TryParse(row.GetValueOrDefault(key),out int n)?n:0;
    private static string T(IReadOnlyDictionary<string,string?> row,string key)=>row.GetValueOrDefault(key)??"";
    internal static async Task<QuestEditSession> Load(CreatedQuest entry,MySqlConnection? connection=null,MySqlTransaction? transaction=null)
    {
        using var owned=connection is null?await DatabaseConnection.OpenAsync(CatalogRepository.Database):null;var db=connection??owned!;var tx=transaction;if(connection is null)await Initialize(db);if(entry.State!="Active")throw new InvalidOperationException("Deleted quests cannot be edited.");
        async Task<Dictionary<string,string?>> One(string table,string key,long id)=>(await WorldDrops.Query(db,tx,$"SELECT * FROM {QuestCreation.World}.{table} WHERE `{key}`={id}")).SingleOrDefault()??throw new InvalidOperationException("Missing "+table+" row. Refresh the list.");
        string expected=await CreatedQuests.Capture(entry,db,tx);var q=await One("quest_template","ID",entry.QuestId);var a=await One("quest_template_addon","ID",entry.QuestId);var offer=await One("quest_offer_reward","ID",entry.QuestId);var request=await One("quest_request_items","ID",entry.QuestId);var npc=await One("creature_template","entry",entry.NpcId);var spawn=await One("creature","guid",checked((long)entry.SpawnId));var details=(await WorldDrops.Query(db,tx,$"SELECT * FROM {QuestCreation.World}.quest_details WHERE ID={entry.QuestId}")).SingleOrDefault()??[];var ends=await WorldDrops.Query(db,tx,$"SELECT * FROM {QuestCreation.World}.creature_questender WHERE quest={entry.QuestId}");if(ends.Count!=1)throw new InvalidOperationException("This quest has multiple or missing turn-in NPCs. Resolve its links before editing.");
        var triggers=await WorldDrops.Query(db,tx,$"SELECT * FROM {QuestCreation.World}.areatrigger_involvedrelation WHERE quest={entry.QuestId}");var objectives=(await WorldDrops.Query(db,tx,$"SELECT * FROM {QuestCreation.World}.quest_objectives WHERE QuestID={entry.QuestId} ORDER BY `Order`,ID")).Select(r=>new QuestObjectiveDraft(N(r,"ID"),N(r,"Type"),N(r,"Type")==10?triggers.Select(t=>N(t,"id")).SingleOrDefault():N(r,"ObjectID"),N(r,"Type")==10?1:N(r,"Amount"),T(r,"Description"))).ToList();if(objectives.Any(o=>!QuestDefinitions.Types.ContainsKey(o.Type)))throw new InvalidOperationException("This quest contains a scripted objective not supported by the form; no data has been changed.");
        var guaranteed=Enumerable.Range(1,4).Where(i=>N(q,"RewardItem"+i)>0).Select(i=>new QuestItemReward(N(q,"RewardItem"+i),N(q,"RewardAmount"+i))).ToList();var choices=Enumerable.Range(1,6).Where(i=>N(q,"RewardChoiceItemID"+i)>0).Select(i=>new QuestItemReward(N(q,"RewardChoiceItemID"+i),N(q,"RewardChoiceItemQuantity"+i))).ToList();var rep=Enumerable.Range(1,5).Where(i=>N(q,"RewardFactionID"+i)>0).Select(i=>new QuestReputationReward(N(q,"RewardFactionID"+i),N(q,"RewardFactionOverride"+i)/100)).ToList();
        uint flags=uint.Parse(T(q,"Flags"),CultureInfo.InvariantCulture);int special=N(a,"SpecialFlags");int xp=await RewardAmount("QuestXP",q,"RewardXPDifficulty","RewardXPMultiplier"),money=await RewardAmount("QuestMoneyReward",q,"RewardMoneyDifficulty","RewardMoneyMultiplier");
        var options=new QuestOptions{Objectives=objectives,Guaranteed=guaranteed,Choices=choices,Reputation=rep,CompletionLog=T(q,"QuestCompletionLog"),IncompleteText=T(request,"CompletionText"),AreaText=T(q,"AreaDescription"),MaxLevel=N(a,"MaxLevel"),TimeSeconds=N(q,"TimeAllowed"),SuggestedPlayers=Math.Max(1,N(q,"SuggestedGroupNum")),QuestInfo=N(q,"QuestInfoID"),QuestSort=N(q,"QuestSortID"),Repeat=(flags&4096)!=0?"Daily":(flags&32768)!=0?"Weekly":(special&16)!=0?"Monthly":(special&1)!=0?"Repeatable":"Once",Shareable=(flags&8)!=0,RaidAllowed=(flags&64)!=0,AutoAccept=(flags&524288)!=0,Races=ulong.Parse(T(q,"AllowableRaces"),CultureInfo.InvariantCulture),Classes=(uint)N(a,"AllowableClasses"),PreviousQuest=N(a,"PrevQuestID"),NextQuest=N(a,"NextQuestID"),ExclusiveGroup=N(a,"ExclusiveGroup"),RequiredSkill=N(a,"RequiredSkillID"),RequiredSkillPoints=N(a,"RequiredSkillPoints"),RequiredRepFaction=N(a,"RequiredMinRepFaction"),RequiredRepValue=N(a,"RequiredMinRepValue"),SourceItem=N(q,"StartItem"),SourceCount=Math.Max(1,N(a,"ProvidedItemCount")),SourceSpell=N(a,"SourceSpellID"),RewardSpell=N(q,"RewardSpell"),EndNpc=N(ends[0],"id")==entry.NpcId?0:N(ends[0],"id"),AcceptEmote=N(details,"Emote1"),CompleteEmote=N(offer,"Emote1"),IncompleteEmote=N(request,"EmoteOnIncomplete")};
        var draft=new QuestDraft(T(npc,"name"),T(q,"LogTitle"),T(q,"LogDescription"),T(q,"QuestDescription"),T(offer,"RewardText"),N(q,"QuestLevel"),N(q,"MinLevel"),guaranteed.FirstOrDefault()?.Item??0,guaranteed.FirstOrDefault()?.Count??0,true,xp,money){Options=options};
        if(await CreatedQuests.Capture(entry,db,tx)!=expected)throw new InvalidOperationException("The quest changed while loading. Open it again.");return new(entry,draft,expected,spawn);
    }
    private static async Task<int> RewardAmount(string table,Dictionary<string,string?> quest,string index,string multiplier){var rows=await ItemModelAssets.Shared.Table(table);if(!rows.TryGetValue(N(quest,"QuestLevel"),out var row))return 0;float.TryParse(T(quest,multiplier),NumberStyles.Float,CultureInfo.InvariantCulture,out float scale);return checked((int)Math.Round(TooltipData.Number(row,"Difficulty"+(N(quest,index)+1))*scale));}
    internal static async Task SaveCore(MySqlConnection db,MySqlTransaction tx,QuestEditSession session,QuestDraft draft,QuestPlacement? move=null)
    {
        var entry=session.Entry;var audit=(await WorldDrops.Query(db,tx,$"SELECT * FROM {QuestCreation.History} WHERE NpcId={entry.NpcId} AND QuestId={entry.QuestId} FOR UPDATE")).SingleOrDefault()??throw new InvalidOperationException("Creation record missing.");if(audit["OperationId"]!=entry.OperationId||audit["DeletedUtc"] is not null||audit["SnapshotJson"]!=entry.SnapshotJson)throw new InvalidOperationException("Creation record changed. Refresh before editing.");
        string before=await CreatedQuests.Capture(entry,db,tx,true);if(before!=session.Expected)throw new InvalidOperationException("This quest changed since it was opened. Reload it before saving.");QuestCreation.ValidateContent(draft);await QuestDefinitions.Apply(db,tx,entry.QuestId,entry.NpcId,draft,true);await QuestDefinitions.Update(db,tx,"creature_template","entry",entry.NpcId,new(){["name"]=draft.NpcName.Trim(),["femaleName"]=draft.NpcName.Trim()});
        if(move is not null){QuestCreation.Validate(draft,move);var current=await QuestCreation.Capture(move.CharacterId,db,tx,true);if(current.PositionKey!=move.PositionKey)throw new InvalidOperationException("Placement character moved. Capture it again.");await QuestDefinitions.Update(db,tx,"creature","guid",checked((long)entry.SpawnId),new(){["map"]=move.Map.ToString(CultureInfo.InvariantCulture),["zoneId"]=move.Zone.ToString(CultureInfo.InvariantCulture),["position_x"]=move.X.ToString("R",CultureInfo.InvariantCulture),["position_y"]=move.Y.ToString("R",CultureInfo.InvariantCulture),["position_z"]=move.Z.ToString("R",CultureInfo.InvariantCulture),["orientation"]=move.Facing.ToString("R",CultureInfo.InvariantCulture)});}
        string after=await CreatedQuests.Capture(entry,db,tx);using var log=new MySqlCommand($"INSERT INTO {Events}(EventId,OperationId,Action,BeforeJson,AfterJson,CreatedUtc) VALUES(@id,@op,'Edit',@before,@after,UTC_TIMESTAMP(6))",db,tx);log.Parameters.AddWithValue("@id",Guid.NewGuid().ToString());log.Parameters.AddWithValue("@op",entry.OperationId);log.Parameters.AddWithValue("@before",before);log.Parameters.AddWithValue("@after",after);await log.ExecuteNonQueryAsync();using var title=new MySqlCommand($"UPDATE {QuestCreation.History} SET Title=@title WHERE OperationId=@op",db,tx);title.Parameters.AddWithValue("@title",draft.Title.Trim());title.Parameters.AddWithValue("@op",entry.OperationId);await title.ExecuteNonQueryAsync();
    }
    internal static Task<bool> Save(QuestEditSession session,QuestDraft draft,QuestPlacement? move=null)=>ContentEditing.Transaction(async(db,tx)=>{await SaveCore(db,tx,session,draft,move);return true;});
}
